function validate([points, queries]) {
  if (!Array.isArray(points) || points.length < 1 || points.length > 500) return 'points needs 1 to 500 entries.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 500) return 'queries needs 1 to 500 entries.';
  const ok = (v, lo) => Number.isInteger(v) && v >= lo && v <= 500;
  if (points.some(p => !Array.isArray(p) || p.length !== 2 || !ok(p[0], 0) || !ok(p[1], 0))) return 'Each point is [x, y] with integers from 0 to 500.';
  if (queries.some(q => !Array.isArray(q) || q.length !== 3 || !ok(q[0], 0) || !ok(q[1], 0) || !ok(q[2], 1))) return 'Each query is [x, y, r] with x and y from 0 to 500 and r from 1 to 500.';
  return null;
}

