function countPoints(points, queries) {
  const answer = [];

  for (const [cx, cy, r] of queries) {
    let count = 0;
    for (const [x, y] of points) {
      const dx = x - cx;
      const dy = y - cy;
      if (dx * dx + dy * dy <= r * r) {
        count++;
      }
    }
    answer.push(count);
  }
  return answer;
}

