function countPoints(points, queries) {
  // Tally points per lattice cell, then sweep every lattice cell of each circle's bounding box.
  const tally = new Map();
  let maxX = 0, maxY = 0;
  for (const [x, y] of points) {
    const key = x * 1001 + y;
    tally.set(key, (tally.get(key) || 0) + 1);
    maxX = Math.max(maxX, x);
    maxY = Math.max(maxY, y);
  }
  return queries.map(([qx, qy, radius]) => {
    let total = 0;
    for (let x = Math.max(0, qx - radius); x <= Math.min(maxX, qx + radius); x++) {
      for (let y = Math.max(0, qy - radius); y <= Math.min(maxY, qy + radius); y++) {
        if ((x - qx) ** 2 + (y - qy) ** 2 > radius ** 2) continue;
        total += tally.get(x * 1001 + y) || 0;
      }
    }
    return total;
  });
}

