function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const points = Array.from({ length: 500 }, () => [int(0, 500), int(0, 500)]);
    const queries = Array.from({ length: 500 }, () => [int(0, 500), int(0, 500), int(1, 500)]);
    return [points, queries];
  }
  const span = rand() < 0.5 ? 4 : 12;
  const points = Array.from({ length: int(1, 8) }, () => [int(0, span), int(0, span)]);
  const queries = Array.from({ length: int(1, 6) }, () => [int(0, span), int(0, span), int(1, span)]);
  return [points, queries];
}
